import{_ as e,o,c as a,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Operations Toolkit Ideas and Prototypes","description":"","frontmatter":{"title":"Ceph Operations Toolkit Ideas and Prototypes","date":"2026-06-26T00:00:00.000Z","updated":"2026-06-26T00:00:00.000Z","tags":["Ceph","分布式存储","监控","性能优化","会议纪要"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_Operations_Toolkit_Ideas_and_Prototypes.md","filePath":"posts/2026/Ceph_Operations_Toolkit_Ideas_and_Prototypes.md","lastUpdated":null}'),s={name:"posts/2026/Ceph_Operations_Toolkit_Ideas_and_Prototypes.md"};function n(i,t,l,d,p,c){return o(),a("div",null,[...t[0]||(t[0]=[r('<h2 id="会议纪要-ceph-operations-toolkit-ideas-and-prototypes" tabindex="-1">会议纪要：Ceph Operations Toolkit Ideas and Prototypes <a class="header-anchor" href="#会议纪要-ceph-operations-toolkit-ideas-and-prototypes" aria-label="Permalink to &quot;会议纪要：Ceph Operations Toolkit Ideas and Prototypes&quot;">​</a></h2><p>本次会议由 Clyo 的 Dan 主持，采用现场演示和互动头脑风暴的形式，展示了三个正在开发中的 Ceph 运维工具原型，旨在收集社区反馈。</p><h3 id="一、ceph-analyzer-与配置版本对比工具" tabindex="-1">一、Ceph Analyzer 与配置版本对比工具 <a class="header-anchor" href="#一、ceph-analyzer-与配置版本对比工具" aria-label="Permalink to &quot;一、Ceph Analyzer 与配置版本对比工具&quot;">​</a></h3><p>Dan 首先介绍了已上线的 <strong>Ceph Analyzer</strong> 网站（analyzer.clyo.com）。用户可上传 <code>ceph report</code> 输出，系统会给出配置评分（如 A+、B- 等）。</p><p>新功能亮点是 <strong>Config Viewer</strong>：支持按版本查看所有配置选项及其文档，并可在两个版本之间进行 diff 对比。例如从 Quincy 17.2.7 升级到 Reef 18.2.8 时，可直观看到所有配置差异——哪些选项被新增、删除或修改了默认值（如 NVMe <code>beacon_grace</code> 从 10 改为 7）。Dan 强调这比过去用 <code>git diff</code> 对比 release notes 高效得多。</p><p><strong>Ceph Versions Browser</strong> 是仍在早期开发的新工具，目标是回答运维人员最常问的问题：&quot;我能升级到某个版本吗？怎么升？&quot;该工具会列出 Clyo 推荐的版本（非社区推荐），并标注每个版本的已知 <strong>critical bugs</strong>，链接到对应的 tracker issue。</p><p>Dan 在演示中列举了几个关键 bug 作为参考：</p><ul><li><strong>RGW 数据丢失 bug</strong>：与 garbage collection 相关，影响 Ceph 17.x 和 18.x 全部版本，19.2.4 已修复，Tentacle 中也已修复</li><li><strong>OSD 使用 elastic shared blobs 部署的问题</strong>：影响特定 point release</li></ul><p>Dan 还提到了一个关于 AI 可靠性的有趣类比——<strong>Gell-Mann Amnesia Effect</strong>：人们读报纸时，对自己专业领域的错误一眼看穿，但对其他领域却选择相信。AI 生成的内容也是如此，表面看起来很专业，但细节上可能完全错误。他提到有客户拿着 Claude 给出的 Ceph 运维建议来咨询，结果发现如果照做会丢失所有数据。</p><h3 id="二、durability-calculator-持久性计算器" tabindex="-1">二、Durability Calculator（持久性计算器） <a class="header-anchor" href="#二、durability-calculator-持久性计算器" aria-label="Permalink to &quot;二、Durability Calculator（持久性计算器）&quot;">​</a></h3><p>去年 Dan 展示过一个命令行的&quot;集群可用性有几个 9&quot;的计算器，如今一位工程师将其做成了交互式 <strong>Web UI</strong>。</p><p>工具支持调整多种参数：</p><ul><li><strong>failure domain</strong>（host / rack / room）</li><li>副本策略：三副本 vs Erasure Coding（如 4+2、8+2）</li><li>OSD 数量、磁盘容量、<strong>AFR</strong>（年化故障率，默认 2%）</li><li><strong>recovery speed</strong>（恢复速度，MB/s）</li><li><strong>recovery sleep</strong> 设置</li><li><strong>PGs per OSD</strong></li><li><strong>correlation fudge</strong>（关联因子，反映一块盘故障后其他盘更易故障的概率）</li></ul><p><strong>关键发现演示</strong>：</p><ol><li><strong>Erasure Coding vs 三副本</strong>：4+2 EC 的持久性（9 nines）低于三副本（11 nines），8+2 EC 更低（7 nines）。Dan 建议生产环境优先使用三副本。</li><li><strong>Recovery sleep 影响巨大</strong>：将 recovery sleep 从 10ms 改为 900ms，持久性可能下降 2 个 9。有些用户为保护客户 IO 将 sleep 设为 10 秒，结果导致 PG 长时间 inactive，后续故障叠加，反而造成更严重的数据风险。Dan 称这是&quot;穷人版 QoS&quot;，但也提醒过度使用会适得其反。</li><li><strong>PGs per OSD 参数扫描</strong>：工具支持从 50 到 300 的参数扫描，结果呈非线性变化，存在某些&quot;甜蜜区间&quot;。</li></ol><p>该工具计划近期上线网站。</p><h3 id="三、rescue-container-救援容器" tabindex="-1">三、Rescue Container（救援容器） <a class="header-anchor" href="#三、rescue-container-救援容器" aria-label="Permalink to &quot;三、Rescue Container（救援容器）&quot;">​</a></h3><p>Dan 团队近期进行了多次 CephFS 灾难恢复演练——故意以不同方式破坏 CephFS 集群再修复。<strong>2026-06-24 将举办相关 webinar</strong>。</p><p>演练中发现一个重要问题：<strong>Ceph 17.x、18.x 甚至更早版本的 CephFS recovery 工具存在 bug</strong>——在特定类型的 corruption 下会静默 abort，不告知用户，导致用户继续执行后续步骤使情况恶化。只有 <strong>v20.2.1+ 的 recovery scripts</strong> 才能正常工作。</p><p>因此团队开发了一个 <strong>Rescue Container</strong>：用户可下载指定版本的容器镜像，内含已打补丁的工具，作为灾难恢复的&quot;急救包&quot;。</p><h3 id="四、cli-工具与-tui-dashboard" tabindex="-1">四、CLI 工具与 TUI Dashboard <a class="header-anchor" href="#四、cli-工具与-tui-dashboard" aria-label="Permalink to &quot;四、CLI 工具与 TUI Dashboard&quot;">​</a></h3><p>Dan 还演示了两个命令行工具：</p><ol><li><p><strong>auto 工具</strong>：一个 shell 脚本，可一键拉起指定版本的容器，内含所有运维工具。容器内可运行 <code>checkup</code> 命令（Analyzer 的 CLI 版本），以及 CephFS session 分析、OSD 性能分析等工具。Dan 称之为&quot;带好东西的 cephadm shell&quot;。</p></li><li><p><strong>TUI Dashboard</strong>：一个基于终端的文本 UI 管理界面，灵感来自 Kubernetes 生态中的类似工具。最初为 RGW admin 设计（管理用户、bucket、quota、GC、bucket lifecycle 等），后扩展为完整的 Ceph 管理工具。支持 <code>ceph status</code> 可视化、用户管理、bucket 浏览等操作，还包含一个可爱的章鱼吉祥物，集群健康时&quot;开心&quot;，出问题时&quot;难过&quot;。</p></li></ol><h3 id="总结与后续计划" tabindex="-1">总结与后续计划 <a class="header-anchor" href="#总结与后续计划" aria-label="Permalink to &quot;总结与后续计划&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>状态</th><th>预计上线</th></tr></thead><tbody><tr><td>Config Viewer / Diff</td><td>已上线</td><td>analyzer.clyo.com</td></tr><tr><td>Ceph Versions Browser</td><td>早期开发</td><td>数周内 LinkedIn/邮件列表发布</td></tr><tr><td>Durability Calculator Web UI</td><td>开发中</td><td>近期上线</td></tr><tr><td>Rescue Container</td><td>开发中</td><td>持续更新</td></tr><tr><td>CLI auto 工具 / TUI Dashboard</td><td>原型阶段</td><td>未定</td></tr></tbody></table><p>Dan 表示所有工具的目标都源自实际运维痛点（&quot;我希望在 CERN 时就有这些工具&quot;），欢迎社区反馈和贡献。</p>',26)])])}const g=e(s,[["render",n]]);export{u as __pageData,g as default};
